export const QUELLTEXTE: Readonly<Record<string, string>> = {
  "projects/beispiel-app/src/index.html": "<!doctype html>\n<html lang=\"de\" class=\"z-root\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <title>Gameserver · Zenit-Hosting Beispiel</title>\n    <base href=\"/\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <link rel=\"icon\" type=\"image/x-icon\" href=\"favicon.ico\" />\n  </head>\n  <!-- z-root belongs on <html> and on <body> (README, step 2): it carries\n       background, text color, the three fonts, `font: inherit` for controls and\n       the focus ring. Overlays (dialog, menu, toast) attach to <body> and\n       inherit the same custom properties from there. -->\n  <body class=\"z-root\">\n    <app-root></app-root>\n  </body>\n</html>\n",
  "projects/beispiel-app/src/styles.css": "/* #region schriften */\n/* Fonts, self-hosted, exactly as step 3 of the package README describes them:\n   Material Icons for z-icon, Inter 400/500/600 as body, Space Grotesk 600/700\n   as display, JetBrains Mono 400/600 as mono. No request to Google.\n   The cascade layer is required: material-icons sets its own font-size on\n   .material-icons and is loaded after zenit-ui.css, so without the layer the\n   icon would be 24px inside a 20px box. */\n@import 'material-icons/iconfont/filled.css' layer(schriften);\n@import '@fontsource/inter/400.css';\n@import '@fontsource/inter/500.css';\n@import '@fontsource/inter/600.css';\n@import '@fontsource/space-grotesk/600.css';\n@import '@fontsource/space-grotesk/700.css';\n@import '@fontsource/jetbrains-mono/400.css';\n@import '@fontsource/jetbrains-mono/600.css';\n/* #endregion */\n\n/* Everything below is the whole stylesheet of this application. The building\n   blocks bring their own classes, so an application only spaces the regions of\n   the page and styles what the library has no block for: the code display of\n   this example. Values come from tokens.css only, no hex, no pixel literals,\n   no radius of its own. */\n\n/* Skip link: visually hidden until it takes focus, then a real 40px target\n   above the header (15-zustaende.md, \"Tastatur\"). */\n.app-skip {\n  position: absolute;\n  left: var(--space-4);\n  top: var(--space-4);\n  z-index: var(--z-header);\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n}\n.app-skip:focus {\n  display: inline-flex;\n  align-items: center;\n  width: auto;\n  height: auto;\n  min-height: var(--control-md);\n  padding: 0 var(--space-3);\n  border-radius: var(--radius-sm);\n  background: var(--surface-raised);\n  clip-path: none;\n}\n\n/* The content area between header and footer. */\n.app-main {\n  display: block;\n  padding-block: var(--space-6) var(--space-9);\n}\n\n/* Customer area (CLAUDE.md, \"Abstand und Layout\"): PageHeader, then space-6,\n   then the panels, which keep space-5 between them through .z-stack. */\n.app-page {\n  display: grid;\n  gap: var(--space-6);\n}\n\n/* Filter row: search and status select in one line, from 640px on, with the\n   select at sidebar width (Select README). Below that they stack, so nothing\n   scrolls sideways at 360px. */\n.app-filter {\n  display: grid;\n  gap: var(--space-3);\n  align-items: end;\n  grid-template-columns: minmax(0, 1fr);\n}\n@media (min-width: 640px) {\n  .app-filter {\n    grid-template-columns: minmax(0, 1fr) var(--sidebar);\n  }\n}\n\n/* Column head above the amounts. The cells themselves get their alignment and\n   the mono face from [zRowNum]; the head keeps the caption style of the row\n   head and only moves to the right. */\n.app-rechts {\n  text-align: right;\n}\n\n/* Sections of the page \"Einbindung\": a heading, a sentence, a code block,\n   separated by a 1px line instead of a frame (CLAUDE.md, \"Rahmen nur um\n   Werkzeuge\"). */\n.app-abschnitt {\n  display: grid;\n  gap: var(--space-4);\n  padding-top: var(--space-6);\n  border-top: 1px solid var(--border);\n}\n.app-abschnitt h2,\n.app-abschnitt p {\n  margin: 0;\n  max-width: var(--measure);\n}\n\n/* Disclosure over a code block. Same shape as z-faq, but a native details, so\n   that a <pre> is allowed inside it (z-faq projects into a <p>). */\n.app-code-faq {\n  border-top: 1px solid var(--border);\n}\n.app-code-faq > summary {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--space-4);\n  min-height: var(--control-md);\n  padding-block: var(--space-2);\n  color: var(--text-muted);\n  font-weight: 500;\n  cursor: pointer;\n  list-style: none;\n}\n.app-code-faq > summary::-webkit-details-marker {\n  display: none;\n}\n.app-code-faq > summary::after {\n  content: '+';\n  font-family: var(--font-mono);\n}\n.app-code-faq[open] > summary::after {\n  content: '−';\n}\n.app-code-faq[open] > summary {\n  color: var(--text);\n}\n\n/* Several blocks inside one disclosure. */\n.app-code-gruppe {\n  display: grid;\n  gap: var(--space-5);\n  padding-bottom: var(--space-4);\n}\n\n/* Code block: caption line, then the framed area. */\n.app-code {\n  display: grid;\n  gap: var(--space-2);\n  margin: 0;\n  min-width: 0;\n}\n.app-code__kopf {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--space-2);\n}\n.app-code__datei {\n  color: var(--text-subtle);\n}\n/* The only element of the page that may scroll sideways, capped in height so\n   that a long file does not push everything else off the screen. */\n.app-code__flaeche {\n  max-height: calc(var(--space-9) * 4);\n  overflow: auto;\n  border: 1px solid var(--border);\n  border-radius: var(--radius-md);\n  background: var(--bg);\n}\n.app-code__text {\n  margin: 0;\n  padding: var(--space-4);\n}\n",
  "projects/beispiel-app/src/main.ts": "import { bootstrapApplication } from '@angular/platform-browser';\nimport { appConfig } from './app/app.config';\nimport { App } from './app/app';\n\nbootstrapApplication(App, appConfig).catch((err) => console.error(err));\n",
  "projects/beispiel-app/src/app/app.config.ts": "import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';\nimport { provideRouter, withComponentInputBinding } from '@angular/router';\nimport { provideZenitTheme } from 'zenit-ui';\nimport { routes } from './app.routes';\n\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideBrowserGlobalErrorListeners(),\n    // withComponentInputBinding() hands query parameters to matching component\n    // inputs. That is how `?zustand=laden` reaches the page without the page\n    // having to subscribe to the router.\n    provideRouter(routes, withComponentInputBinding()),\n    // #region theme\n    // Scheme and accent live in themes.css; the provider applies the stored or\n    // the default choice before the first frame and keeps it in localStorage.\n    // 'system' follows prefers-color-scheme until someone picks a scheme.\n    provideZenitTheme({ defaultScheme: 'system' }),\n    // Another language for the library's own texts would be:\n    // provideZenitLabels(Z_LABELS_EN),\n    // #endregion\n  ],\n};\n",
  "projects/beispiel-app/src/app/app.routes.ts": "import { Routes } from '@angular/router';\n\n/**\n * Two pages, both lazy. `/` redirects to the Gameserver list, which is the page\n * this example is about; `/einbindung` explains how it is wired.\n */\nexport const routes: Routes = [\n  { path: '', pathMatch: 'full', redirectTo: 'gameserver' },\n  {\n    path: 'gameserver',\n    loadComponent: () => import('./pages/gameserver/gameserver').then((m) => m.Gameserver),\n  },\n  {\n    path: 'einbindung',\n    loadComponent: () => import('./pages/einbindung/einbindung').then((m) => m.Einbindung),\n  },\n];\n",
  "projects/beispiel-app/src/app/layout/shell/shell.ts": "import { Component } from '@angular/core';\nimport { RouterLink, RouterLinkActive, RouterOutlet } from '@angular/router';\nimport {\n  ZAppHeader,\n  ZBrand,\n  ZFooter,\n  ZFooterBase,\n  ZHeaderEnd,\n  ZHeaderLink,\n  ZToastOutlet,\n} from 'zenit-ui';\nimport { GUTHABEN, KUNDEN_LINKS, NUTZER } from '../../gameserver/beispieldaten';\nimport { ThemeControl } from '../theme-control/theme-control';\n\n/**\n * Layout of the customer area: header, content, footer (10-seitenmuster.md,\n * \"Seite im Kundenbereich\"). Every page of a real application sits in here, so\n * the shell is the only place that knows about navigation, theme control and\n * toast outlet.\n */\n@Component({\n  selector: 'app-shell',\n  imports: [\n    RouterLink,\n    RouterLinkActive,\n    RouterOutlet,\n    ThemeControl,\n    ZAppHeader,\n    ZBrand,\n    ZFooter,\n    ZFooterBase,\n    ZHeaderLink,\n    ZHeaderEnd,\n    ZToastOutlet,\n  ],\n  template: `\n    <!-- First tab stop of the page, visible only while focused. -->\n    <a class=\"app-skip body-sm\" href=\"#inhalt\">Zum Hauptinhalt springen</a>\n\n    <!-- Header, content and footer share the same z-container, so brand,\n         page title and copyright stand on one line at every width. -->\n    <div class=\"z-container\">\n      <!-- #region kopfzeile -->\n      <z-app-header navLabel=\"Hauptnavigation\">\n        <!-- The logo file belongs to the repository of the real site; the design\n             system ships none, so the brand is its name in the display face. -->\n        <span zBrand>Zenit</span>\n        @for (link of links; track link.name) {\n          @if (link.route) {\n            <a\n              zHeaderLink\n              [routerLink]=\"link.route\"\n              routerLinkActive\n              #aktiv=\"routerLinkActive\"\n              [active]=\"aktiv.isActive\"\n              >{{ link.name }}</a\n            >\n          } @else {\n            <!-- The other pages of the customer area are not part of this\n                 example. They stay links so the header keeps its real shape. -->\n            <a zHeaderLink href=\"#\" (click)=\"$event.preventDefault()\">{{ link.name }}</a>\n          }\n        }\n        <!-- Credit in mono without a red pill, and a link to the billing page\n             (AppHeader README). The label spells out what the number is, because\n             \"25,00 €\" alone says nothing when read out loud. -->\n        <a\n          zHeaderLink\n          zHeaderEnd\n          class=\"z-mono\"\n          href=\"#\"\n          aria-label=\"Guthaben 25,00 Euro, zur Abrechnung\"\n          (click)=\"$event.preventDefault()\"\n          >{{ guthaben }}</a\n        >\n        <!-- Colour scheme and accent, see layout/theme-control. -->\n        <app-theme-control zHeaderEnd />\n        <!-- Decorative: the name is already in the account menu of a real app. -->\n        <span zHeaderEnd class=\"z-avatar\" aria-hidden=\"true\">{{ nutzer }}</span>\n      </z-app-header>\n      <!-- #endregion -->\n    </div>\n\n    <!-- tabindex=\"-1\" lets the skip link move the focus here. z-container keeps\n         the content at most the container width and left aligned. -->\n    <main id=\"inhalt\" tabindex=\"-1\" class=\"z-container app-main\">\n      <router-outlet />\n    </main>\n\n    <div class=\"z-container\">\n      <!-- #region fusszeile -->\n      <z-footer>\n        <!-- Customer area: only the bottom row, copyright left and the legal\n             links right, no link columns (Footer README). Both parts carry\n             zFooterBase, because the row spreads its own children. -->\n        <span zFooterBase>© 2026 Zenit-Hosting</span>\n        <span zFooterBase class=\"z-cluster\">\n          @for (link of rechtliches; track link) {\n            <a href=\"#\" (click)=\"$event.preventDefault()\">{{ link }}</a>\n          }\n        </span>\n      </z-footer>\n      <!-- #endregion -->\n    </div>\n\n    <!-- #region toastauslass -->\n    <!-- Once per application, at the end of the layout (README, step 4). -->\n    <z-toast-outlet />\n    <!-- #endregion -->\n  `,\n})\nexport class Shell {\n  protected readonly guthaben = GUTHABEN;\n  protected readonly nutzer = NUTZER;\n  protected readonly links = KUNDEN_LINKS;\n  protected readonly rechtliches = ['Impressum', 'Datenschutz', 'AGB', 'Widerruf'];\n}\n",
  "projects/beispiel-app/src/app/layout/theme-control/theme-control.ts": "import { CdkMenuTrigger } from '@angular/cdk/menu';\nimport { Component, computed, inject } from '@angular/core';\nimport { ZButton, ZIcon, ZMenu, ZMenuItem, ZTheme } from 'zenit-ui';\n\n/** The schemes of `themes.css` plus the one that follows the operating system. */\nconst SCHEMATA = [\n  { id: 'dark', name: 'Dunkel', icon: 'dark_mode' },\n  { id: 'light', name: 'Hell', icon: 'light_mode' },\n  { id: 'contrast', name: 'Kontrast', icon: 'contrast' },\n  { id: 'system', name: 'System', icon: 'brightness_auto' },\n] as const;\n\n/** The four accents of `accents.css`. `rot` is the default and carries no attribute. */\nconst AKZENTE = [\n  { id: 'rot', name: 'Rot' },\n  { id: 'blau', name: 'Blau' },\n  { id: 'gruen', name: 'Grün' },\n  { id: 'violett', name: 'Violett' },\n] as const;\n\n/**\n * Colour scheme and accent, for the end slot of the header.\n *\n * Two menus instead of two `z-select`s: a select needs a visible label and a\n * width of its own, and at 360px the header already carries brand, menu\n * button, credit and avatar. An icon button is 40px on mobile and says its\n * current value in its `aria-label`, so nothing is lost. The menus come from\n * the library, the state from `ZTheme`, which also stores it in\n * `localStorage`; this component holds none of its own.\n */\n@Component({\n  selector: 'app-theme-control',\n  imports: [CdkMenuTrigger, ZButton, ZIcon, ZMenu, ZMenuItem],\n  host: { class: 'z-cluster' },\n  template: `\n    <button\n      zBtn=\"ghost\"\n      size=\"sm\"\n      iconOnly\n      type=\"button\"\n      [attr.aria-label]=\"'Farbschema wählen, aktuell ' + schemaName()\"\n      [cdkMenuTriggerFor]=\"schemaMenue\"\n    >\n      <z-icon [name]=\"schemaIcon()\" />\n    </button>\n    <ng-template #schemaMenue>\n      <z-menu>\n        @for (schema of schemata; track schema.id) {\n          <button\n            zMenuItem\n            [icon]=\"schema.icon\"\n            [attr.aria-current]=\"schema.id === theme.scheme() ? 'true' : null\"\n            (triggered)=\"theme.setScheme(schema.id)\"\n          >\n            {{ schema.name }}\n          </button>\n        }\n      </z-menu>\n    </ng-template>\n\n    <button\n      zBtn=\"ghost\"\n      size=\"sm\"\n      iconOnly\n      type=\"button\"\n      [attr.aria-label]=\"'Akzentfarbe wählen, aktuell ' + akzentName()\"\n      [cdkMenuTriggerFor]=\"akzentMenue\"\n    >\n      <z-icon name=\"palette\" />\n    </button>\n    <ng-template #akzentMenue>\n      <z-menu>\n        @for (akzent of akzente; track akzent.id) {\n          <button\n            zMenuItem\n            [attr.aria-current]=\"akzent.id === theme.accent() ? 'true' : null\"\n            (triggered)=\"theme.setAccent(akzent.id)\"\n          >\n            {{ akzent.name }}\n          </button>\n        }\n      </z-menu>\n    </ng-template>\n  `,\n})\nexport class ThemeControl {\n  protected readonly theme = inject(ZTheme);\n  protected readonly schemata = SCHEMATA;\n  protected readonly akzente = AKZENTE;\n\n  /** German name of the chosen scheme, for the label of the trigger. */\n  protected readonly schemaName = computed(\n    () => SCHEMATA.find((s) => s.id === this.theme.scheme())?.name ?? this.theme.scheme(),\n  );\n\n  /**\n   * Icon of the chosen scheme. In system mode it shows what is applied right\n   * now, so the button never claims a scheme the page is not in.\n   */\n  protected readonly schemaIcon = computed(() => {\n    const gewaehlt = SCHEMATA.find((s) => s.id === this.theme.scheme());\n    return gewaehlt?.id === 'system' || !gewaehlt\n      ? (SCHEMATA.find((s) => s.id === this.theme.resolvedScheme())?.icon ?? 'brightness_auto')\n      : gewaehlt.icon;\n  });\n\n  protected readonly akzentName = computed(\n    () => AKZENTE.find((a) => a.id === this.theme.accent())?.name ?? this.theme.accent(),\n  );\n}\n",
  "projects/beispiel-app/src/app/pages/gameserver/gameserver.ts": "import { Clipboard } from '@angular/cdk/clipboard';\nimport { Component, computed, effect, inject, input, signal } from '@angular/core';\nimport {\n  ZButton,\n  ZDialog,\n  ZField,\n  ZIcon,\n  ZInput,\n  ZInputGroup,\n  ZPageHeader,\n  ZSelect,\n  ZToast,\n} from 'zenit-ui';\nimport { BeispielServer, STATUS_FILTER } from '../../gameserver/beispieldaten';\nimport {\n  filtern,\n  GameserverData,\n  ListenZustand,\n  Simulation,\n} from '../../gameserver/gameserver-data';\nimport { ServerList } from '../../gameserver/server-list/server-list';\nimport { CodeBlock } from '../../shared/code-block/code-block';\nimport { DATEI, quelltext } from '../../shared/quelltexte';\n\n/** The states a reader can call up through `?zustand=`. */\nconst SIMULATIONEN: readonly Simulation[] = ['normal', 'laden', 'leer', 'fehler'];\n\n/**\n * Page \"Gameserver\" of the customer area (10-seitenmuster.md): AppHeader,\n * PageHeader with one fact and one action, then the panels. The page title is\n * the same word as the navigation link.\n *\n * It owns the filter, the feedback and the confirmation; drawing the list is\n * the job of ServerList.\n *\n * Every region carries a disclosure with its own source. A native `details` and\n * not `z-faq`, because that component projects into a `<p>` limited to\n * `measure`, and a `<pre>` inside a `<p>` is invalid HTML that the parser\n * closes early. `nav[zTabs]` with \"Vorschau | Code\" was the alternative; it\n * would show the code by default and put a second interactive layer on every\n * region of a page whose job is to be looked at. A closed `details` stays out\n * of the way, needs no script and is keyboard operable by itself.\n */\n@Component({\n  selector: 'app-gameserver',\n  imports: [\n    CodeBlock,\n    ServerList,\n    ZButton,\n    ZField,\n    ZIcon,\n    ZInput,\n    ZInputGroup,\n    ZPageHeader,\n    ZSelect,\n  ],\n  host: { class: 'app-page' },\n  template: `\n    <!-- #region seitenkopf -->\n    <!-- One fact, and the one primary of this screen (PageHeader README). -->\n    <z-page-header title=\"Gameserver\" sub=\"Abrechnung nach Stunden, nächste Rechnung am 01.10.2026\">\n      <button zBtn=\"primary\" type=\"button\" (click)=\"erstellen()\">\n        <z-icon name=\"add\" />\n        Server erstellen\n      </button>\n    </z-page-header>\n    <!-- #endregion -->\n\n    <details class=\"app-code-faq\">\n      <summary>So ist es eingebunden: Seitenkopf</summary>\n      <app-code-block\n        [code]=\"quellen.seitenkopf\"\n        datei=\"pages/gameserver/gameserver.ts\"\n        sprache=\"Template\"\n      />\n    </details>\n\n    <div class=\"z-stack\">\n      @if (filterSichtbar()) {\n        <!-- #region filterzeile -->\n        <!-- An empty list shows no filters (EmptyState README), so the row only\n             exists while there is something to narrow down. -->\n        <div class=\"app-filter\">\n          <z-field label=\"Suche\" for=\"suche\">\n            <z-input-group icon=\"search\">\n              <input\n                zInput\n                size=\"sm\"\n                id=\"suche\"\n                name=\"suche\"\n                type=\"search\"\n                placeholder=\"Name oder Adresse\"\n                [value]=\"suche()\"\n                (input)=\"sucheSetzen($event)\"\n              />\n            </z-input-group>\n          </z-field>\n          <z-field label=\"Status\" for=\"status\">\n            <z-select size=\"sm\">\n              <select id=\"status\" name=\"status\" (change)=\"statusSetzen($event)\">\n                @for (option of statusOptionen; track option) {\n                  <option [value]=\"option\" [selected]=\"option === status()\">{{ option }}</option>\n                }\n              </select>\n            </z-select>\n          </z-field>\n        </div>\n        <!-- #endregion -->\n\n        <details class=\"app-code-faq\">\n          <summary>So ist es eingebunden: Filterzeile</summary>\n          <app-code-block\n            [code]=\"quellen.filterzeile\"\n            datei=\"pages/gameserver/gameserver.ts\"\n            sprache=\"Template\"\n          />\n        </details>\n      }\n\n      <!-- #region liste -->\n      <app-server-list\n        [server]=\"gefiltert()\"\n        [zustand]=\"listenZustand()\"\n        (kopieren)=\"adresseKopieren($event)\"\n        (neustart)=\"neustart($event)\"\n        (loeschen)=\"loeschen($event)\"\n        (erstellen)=\"erstellen()\"\n        (filterZuruecksetzen)=\"filterZuruecksetzen()\"\n        (erneutLaden)=\"erneutLaden()\"\n      />\n      <!-- #endregion -->\n\n      <details class=\"app-code-faq\">\n        <summary>So ist es eingebunden: Serverliste mit allen Zuständen</summary>\n        <div class=\"app-code-gruppe\">\n          <app-code-block\n            [code]=\"quellen.liste\"\n            datei=\"pages/gameserver/gameserver.ts\"\n            sprache=\"Template\"\n          />\n          <app-code-block\n            [code]=\"quellen.zustaende\"\n            datei=\"gameserver/server-list/server-list.ts\"\n            sprache=\"Template\"\n          />\n          <app-code-block\n            [code]=\"quellen.zeile\"\n            datei=\"gameserver/server-list/server-list.ts\"\n            sprache=\"Template\"\n          />\n          <app-code-block\n            [code]=\"quellen.seitenwahl\"\n            datei=\"gameserver/server-list/server-list.ts\"\n            sprache=\"Template\"\n          />\n        </div>\n      </details>\n\n      <details class=\"app-code-faq\">\n        <summary>So ist es eingebunden: Aktionen mit Toast und Dialog</summary>\n        <app-code-block\n          [code]=\"quellen.aktionen\"\n          datei=\"pages/gameserver/gameserver.ts\"\n          sprache=\"TypeScript\"\n        />\n      </details>\n\n      <details class=\"app-code-faq\">\n        <summary>So ist es eingebunden: Rahmen und Theme-Umschalter</summary>\n        <div class=\"app-code-gruppe\">\n          <app-code-block\n            [code]=\"quellen.kopfzeile\"\n            datei=\"layout/shell/shell.ts\"\n            sprache=\"Template\"\n          />\n          <app-code-block\n            [code]=\"quellen.themeUmschalter\"\n            datei=\"layout/theme-control/theme-control.ts\"\n            sprache=\"TypeScript\"\n          />\n        </div>\n      </details>\n    </div>\n  `,\n})\nexport class Gameserver {\n  private readonly daten = inject(GameserverData);\n  private readonly toast = inject(ZToast);\n  private readonly dialog = inject(ZDialog);\n  private readonly clipboard = inject(Clipboard);\n\n  /**\n   * Query parameter `?zustand=laden|leer|fehler`, handed over by the router\n   * through `withComponentInputBinding()`. Anything else shows the normal list.\n   */\n  readonly zustand = input<string>();\n\n  protected readonly statusOptionen = STATUS_FILTER;\n  protected readonly suche = signal('');\n  protected readonly status = signal(STATUS_FILTER[0]);\n\n  /**\n   * The code the disclosures show, read once from the generated copy of the\n   * real files. Nothing here is written by hand, so the page cannot show code\n   * that the page does not run.\n   */\n  protected readonly quellen = {\n    seitenkopf: quelltext(DATEI.seite, 'seitenkopf'),\n    filterzeile: quelltext(DATEI.seite, 'filterzeile'),\n    liste: quelltext(DATEI.seite, 'liste'),\n    aktionen: quelltext(DATEI.seite, 'aktionen'),\n    zustaende: quelltext(DATEI.liste, 'zustaende'),\n    zeile: quelltext(DATEI.liste, 'zeile'),\n    seitenwahl: quelltext(DATEI.liste, 'seitenwahl'),\n    kopfzeile: quelltext(DATEI.shell, 'kopfzeile'),\n    themeUmschalter: quelltext(DATEI.themeControl),\n  };\n\n  /** Search over name and address, plus the status filter. */\n  protected readonly gefiltert = computed(() =>\n    filtern(this.daten.server(), this.suche(), this.status()),\n  );\n\n  /** A loaded list that the filter narrows down to nothing is its own state. */\n  protected readonly listenZustand = computed<ListenZustand>(() => {\n    const zustand = this.daten.zustand();\n    return zustand === 'liste' && this.gefiltert().length === 0 ? 'gefiltert-leer' : zustand;\n  });\n\n  protected readonly filterSichtbar = computed(() => this.daten.server().length > 0);\n\n  constructor() {\n    // The query parameter is the only trigger for a load, so opening\n    // /gameserver?zustand=fehler shows exactly that state.\n    effect(() => this.daten.laden(this.simulation()));\n  }\n\n  private simulation(): Simulation {\n    const wunsch = this.zustand();\n    return SIMULATIONEN.find((s) => s === wunsch) ?? 'normal';\n  }\n\n  protected sucheSetzen(ereignis: Event): void {\n    this.suche.set((ereignis.target as HTMLInputElement).value);\n  }\n\n  protected statusSetzen(ereignis: Event): void {\n    this.status.set((ereignis.target as HTMLSelectElement).value);\n  }\n\n  protected filterZuruecksetzen(): void {\n    this.suche.set('');\n    this.status.set(STATUS_FILTER[0]);\n  }\n\n  /** The wizard belongs to the real application; here it only says so. */\n  protected erstellen(): void {\n    this.toast.show('Der Assistent gehört in deine Anwendung', { icon: 'info' });\n  }\n\n  protected adresseKopieren(server: BeispielServer): void {\n    this.clipboard.copy(server.adresse);\n    this.toast.show('Adresse kopiert', { icon: 'content_copy' });\n  }\n\n  // #region aktionen\n  /**\n   * Restart needs no dialog (Dialog README). The feedback is a toast: one\n   * sentence, no full stop, in the past participle.\n   */\n  protected neustart(server: BeispielServer): void {\n    this.toast.success(`Neustart für ${server.name} gestartet`);\n  }\n\n  /**\n   * Deleting cannot be undone, so it goes through a confirmation that asks for\n   * the server name. Escape and \"Abbrechen\" return the focus to the menu\n   * button; that comes from the CDK.\n   */\n  protected loeschen(server: BeispielServer): void {\n    // The menu closes only after (triggered) has run and hands the focus back\n    // to the row button. Opening one microtask later makes that button the\n    // element the dialog returns the focus to when it closes.\n    queueMicrotask(() => this.dialogFragen(server));\n  }\n\n  private dialogFragen(server: BeispielServer): void {\n    this.dialog\n      .confirm({\n        title: `Server \"${server.name}\" löschen?`,\n        body: 'Alle Welten, Backups und Zugänge gehen verloren. Das lässt sich nicht rückgängig machen.',\n        confirmLabel: 'Löschen',\n        cancelLabel: 'Abbrechen',\n        danger: true,\n        requireText: server.name,\n        requireLabel: 'Name des Servers',\n      })\n      .subscribe((bestaetigt) => {\n        if (bestaetigt) {\n          this.daten.entfernen(server.id);\n          this.toast.success(`${server.name} gelöscht`);\n        }\n      });\n  }\n  // #endregion\n\n  /** The retry answers normally, so that the error state can be left again. */\n  protected erneutLaden(): void {\n    this.daten.laden('normal');\n  }\n}\n",
  "projects/beispiel-app/src/app/gameserver/gameserver-data.ts": "import { OnDestroy, Service, signal } from '@angular/core';\nimport { BEISPIEL_SERVER, BeispielServer, STATUS_FILTER } from './beispieldaten';\n\n/**\n * Narrows the list: free text over name and address, plus one status. A pure\n * function, so the page keeps a `computed()` of one line and the rule can be\n * tested without a component.\n *\n * @param suche Free text, case is ignored. Empty means everything.\n * @param status One of {@link STATUS_FILTER}; the first entry means everything.\n */\nexport function filtern(\n  server: readonly BeispielServer[],\n  suche: string,\n  status: string,\n): readonly BeispielServer[] {\n  const text = suche.trim().toLowerCase();\n  return server.filter(\n    (eintrag) =>\n      (!text ||\n        eintrag.name.toLowerCase().includes(text) ||\n        eintrag.adresse.toLowerCase().includes(text)) &&\n      (status === STATUS_FILTER[0] || eintrag.statusText === status),\n  );\n}\n\n/**\n * What the page asks for, taken from the query parameter `?zustand=`. `normal`\n * is the default and shows the list.\n */\nexport type Simulation = 'normal' | 'laden' | 'leer' | 'fehler';\n\n/**\n * What the list shows right now. `start` is the first 300 milliseconds of a\n * load: nothing is drawn yet, because a fast answer must not make placeholders\n * flash (15-zustaende.md, \"Lädt\").\n */\nexport type Ladezustand = 'start' | 'skelett' | 'liste' | 'leer' | 'fehler';\n\n/** Everything the list renders, including the case \"filter matches nothing\". */\nexport type ListenZustand = Ladezustand | 'gefiltert-leer';\n\n/** Skeleton rows only after 300 milliseconds (15-zustaende.md, Skeleton README). */\nconst SKELETT_MS = 300;\n\n/** Simulated answer of the server. */\nconst ANTWORT_MS = 600;\n\n/**\n * Source of the server list. In a real application this service calls the API;\n * here it answers from `beispieldaten.ts` after a timer, so that loading, empty\n * and error are real states of the page and not a switch in the template.\n *\n * `@Service()` is the short form of `@Injectable({ providedIn: 'root' })` for\n * singletons (Angular 22).\n */\n@Service()\nexport class GameserverData implements OnDestroy {\n  private readonly liste = signal<readonly BeispielServer[]>([]);\n  private readonly ladezustand = signal<Ladezustand>('start');\n  private timer: ReturnType<typeof setTimeout>[] = [];\n\n  /** The servers that have arrived. Empty while loading and on error. */\n  readonly server = this.liste.asReadonly();\n\n  /** Which of the states the list is in. */\n  readonly zustand = this.ladezustand.asReadonly();\n\n  /**\n   * Starts a load. `laden` keeps the skeleton standing, so that the loading\n   * state can be looked at; every other simulation answers after\n   * {@link ANTWORT_MS}.\n   */\n  laden(simulation: Simulation = 'normal'): void {\n    this.stoppeTimer();\n    this.liste.set([]);\n    this.ladezustand.set('start');\n    this.timer.push(setTimeout(() => this.ladezustand.set('skelett'), SKELETT_MS));\n    if (simulation === 'laden') {\n      return;\n    }\n    this.timer.push(\n      setTimeout(() => {\n        if (simulation === 'fehler') {\n          this.ladezustand.set('fehler');\n          return;\n        }\n        this.liste.set(simulation === 'leer' ? [] : BEISPIEL_SERVER);\n        this.ladezustand.set(simulation === 'leer' ? 'leer' : 'liste');\n      }, ANTWORT_MS),\n    );\n  }\n\n  /** Removes a server after the confirmation. The last one leaves the list empty. */\n  entfernen(id: string): void {\n    this.liste.update((alt) => alt.filter((server) => server.id !== id));\n    if (this.liste().length === 0) {\n      this.ladezustand.set('leer');\n    }\n  }\n\n  /** @internal Angular lifecycle hook: no timer survives the application. */\n  ngOnDestroy(): void {\n    this.stoppeTimer();\n  }\n\n  private stoppeTimer(): void {\n    for (const t of this.timer) {\n      clearTimeout(t);\n    }\n    this.timer = [];\n  }\n}\n",
  "projects/beispiel-app/src/app/gameserver/server-list/server-list.ts": "import { CdkMenuTrigger } from '@angular/cdk/menu';\nimport { Component, computed, input, linkedSignal, output } from '@angular/core';\nimport {\n  ZAlert,\n  ZAlertAction,\n  ZBadge,\n  ZButton,\n  ZEmptyAction,\n  ZEmptyState,\n  ZIcon,\n  ZMenu,\n  ZMenuItem,\n  ZMenuSeparator,\n  ZPagination,\n  ZPanel,\n  ZRow,\n  ZRowMain,\n  ZRowNum,\n  ZRows,\n  ZRowsHead,\n  ZSkeleton,\n} from 'zenit-ui';\nimport { BeispielServer, euro } from '../beispieldaten';\nimport { ListenZustand } from '../gameserver-data';\n\n/** Rows per page. 25 is the default of z-pagination; eight servers need less. */\nconst PRO_SEITE = 6;\n\n/** Number of skeleton rows: as many as a normal answer brings (Skeleton README). */\nconst PLATZHALTER = [1, 2, 3];\n\n/**\n * The server list in all of its states. Presentational: it knows the servers\n * and the state, and it reports what the user wants; loading, deleting and\n * feedback stay in the page.\n *\n * The states come from 15-zustaende.md. Error is an alert instead of the panel,\n * because a page carries at most one alert and it stands above the content\n * (Alert README).\n */\n@Component({\n  selector: 'app-server-list',\n  // ZMenu, ZMenuItem and ZMenuSeparator one by one instead of the bundle\n  // Z_MENU: in the built package its type collapses to (typeof ZMenu)[], so\n  // the Angular compiler no longer sees the other two entries.\n  imports: [\n    CdkMenuTrigger,\n    ZAlert,\n    ZAlertAction,\n    ZBadge,\n    ZButton,\n    ZEmptyAction,\n    ZEmptyState,\n    ZIcon,\n    ZMenu,\n    ZMenuItem,\n    ZMenuSeparator,\n    ZPagination,\n    ZPanel,\n    ZRow,\n    ZRowMain,\n    ZRowNum,\n    ZRows,\n    ZRowsHead,\n    ZSkeleton,\n  ],\n  template: `\n    @if (zustand() === 'fehler') {\n      <!-- An error message names the cause and the next step; the one button\n           is secondary and small (Alert README). -->\n      <z-alert status=\"danger\" title=\"Die Serverliste ist nicht geladen\" icon=\"error\">\n        Das Panel hat nach 30 Sekunden nicht geantwortet. Lade die Liste neu oder öffne ein Ticket.\n        <button zAlertAction zBtn=\"secondary\" size=\"sm\" type=\"button\" (click)=\"erneutLaden.emit()\">\n          Erneut laden\n        </button>\n      </z-alert>\n    } @else {\n      <z-panel\n        title=\"Meine Server\"\n        headingLevel=\"2\"\n        flush\n        [busy]=\"zustand() === 'skelett'\"\n        [attr.aria-label]=\"zustand() === 'skelett' ? 'Server werden geladen' : null\"\n      >\n        <!-- #region zustaende -->\n        @switch (zustand()) {\n          @case ('start') {\n            <!-- The first 300 milliseconds stay empty: an answer that fast must\n                 not make placeholders flash (15-zustaende.md). -->\n          }\n          @case ('skelett') {\n            <z-rows [columns]=\"spalten\">\n              <z-rows-head>\n                <span>Server</span>\n                <span>Status</span>\n                <span>Tarif</span>\n                <span class=\"app-rechts\">Bisher</span>\n                <span></span>\n              </z-rows-head>\n              <!-- Same grid, same row height: the layout must not jump when the\n                   data arrives (Skeleton README). -->\n              @for (platz of platzhalter; track platz) {\n                <div zRow>\n                  <span class=\"z-cluster\">\n                    <z-skeleton thumb />\n                    <z-skeleton width=\"120px\" />\n                  </span>\n                  <z-skeleton width=\"72px\" />\n                  <z-skeleton width=\"48px\" />\n                  <z-skeleton width=\"56px\" />\n                  <span></span>\n                </div>\n              }\n            </z-rows>\n          }\n          @case ('leer') {\n            <!-- The primary \"Server erstellen\" already sits in the PageHeader,\n                 so the same action is secondary here (EmptyState README). -->\n            <z-empty-state title=\"Du hast noch keinen Server\">\n              Der erste Server steht in etwa 60 Sekunden bereit.\n              <button zEmptyAction zBtn=\"secondary\" type=\"button\" (click)=\"erstellen.emit()\">\n                Server erstellen\n              </button>\n            </z-empty-state>\n          }\n          @case ('gefiltert-leer') {\n            <!-- Own sentence: the list is not empty, the filter is too narrow. -->\n            <z-empty-state title=\"Kein Server passt zum Filter\">\n              Ändere die Suche oder wähle wieder alle Status.\n              <button\n                zEmptyAction\n                zBtn=\"secondary\"\n                type=\"button\"\n                (click)=\"filterZuruecksetzen.emit()\"\n              >\n                Filter zurücksetzen\n              </button>\n            </z-empty-state>\n          }\n          @default {\n            <z-rows [columns]=\"spalten\">\n              <z-rows-head>\n                <span>Server</span>\n                <span>Status</span>\n                <span>Tarif</span>\n                <span class=\"app-rechts\">Bisher</span>\n                <span></span>\n              </z-rows-head>\n              @for (server of sichtbar(); track server.id) {\n                <!-- #region zeile -->\n                <!--\n                  A row with its own actions is a <div>, not an <a>: a button\n                  inside a link is invalid HTML, and the menu has to be a tab\n                  stop of its own (15-zustaende.md, \"Tastatur\"). The library\n                  documents exactly these two variants on ZRow, and the demo\n                  uses the div variant for every row that carries an action\n                  (\"Geteilt mit mir\" in projects/ui-demo, pages/daten). In an\n                  application with a detail page the first cell becomes\n                  <a [routerLink]=\"['/gameserver', server.id]\"> around\n                  <z-row-main />; this example has only this one page.\n                -->\n                <div zRow>\n                  <z-row-main [title]=\"server.name\" [meta]=\"server.meta\" />\n                  <!-- Status always in the second column, as a word plus dot. -->\n                  <span>\n                    <z-badge [status]=\"server.status\" dot>{{ server.statusText }}</z-badge>\n                  </span>\n                  <!-- Tariff is a tag: neutral, no dot (Badge README). -->\n                  <span\n                    ><z-badge>{{ server.tarif }}</z-badge></span\n                  >\n                  <!-- Amounts right aligned in mono with tabular figures. -->\n                  <span zRowNum>{{ preis(server) }}</span>\n                  <button\n                    zBtn=\"ghost\"\n                    iconOnly\n                    type=\"button\"\n                    [attr.aria-label]=\"'Weitere Aktionen für ' + server.name\"\n                    [cdkMenuTriggerFor]=\"weitere\"\n                  >\n                    <z-icon name=\"more_vert\" />\n                  </button>\n                </div>\n                <ng-template #weitere>\n                  <z-menu>\n                    <button zMenuItem icon=\"content_copy\" (triggered)=\"kopieren.emit(server)\">\n                      Adresse kopieren\n                    </button>\n                    <button zMenuItem icon=\"restart_alt\" (triggered)=\"neustart.emit(server)\">\n                      Neustart\n                    </button>\n                    <!-- Destructive entries sit below the separator and always\n                         open a dialog (Menu README). -->\n                    <z-menu-separator />\n                    <button zMenuItem icon=\"delete\" danger (triggered)=\"loeschen.emit(server)\">\n                      Server löschen\n                    </button>\n                  </z-menu>\n                </ng-template>\n                <!-- #endregion -->\n              }\n            </z-rows>\n          }\n        }\n        <!-- #endregion -->\n        <!-- #region seitenwahl -->\n        <!--\n          The pagination stands alone in its @if: z-panel picks it out of the\n          projected content and puts it in the last row, and a control flow\n          block only reaches a named slot while it holds this single node.\n          z-pagination renders nothing while everything fits on one page.\n        -->\n        @if (zustand() === 'liste') {\n          <z-pagination\n            [(page)]=\"seite\"\n            [pageSize]=\"proSeite\"\n            [total]=\"server().length\"\n            itemLabel=\"Servern\"\n          />\n        }\n        <!-- #endregion -->\n      </z-panel>\n    }\n  `,\n})\nexport class ServerList {\n  /** The servers to show, already filtered by the page. */\n  readonly server = input.required<readonly BeispielServer[]>();\n\n  /** Which state the list is in. */\n  readonly zustand = input.required<ListenZustand>();\n\n  /** \"Adresse kopieren\" from the row menu. */\n  readonly kopieren = output<BeispielServer>();\n\n  /** \"Neustart\" from the row menu. */\n  readonly neustart = output<BeispielServer>();\n\n  /** \"Server löschen\" from the row menu. The page asks before it happens. */\n  readonly loeschen = output<BeispielServer>();\n\n  /** \"Server erstellen\" from the empty state. */\n  readonly erstellen = output<void>();\n\n  /** \"Filter zurücksetzen\" when the filter matches nothing. */\n  readonly filterZuruecksetzen = output<void>();\n\n  /** \"Erneut laden\" from the error alert. */\n  readonly erneutLaden = output<void>();\n\n  protected readonly proSeite = PRO_SEITE;\n  protected readonly platzhalter = PLATZHALTER;\n\n  /**\n   * Shared grid for head and rows, so that status, tariff and amount line up:\n   * name, status, tariff, amount, action button (ServerList README). Below\n   * 640px the stylesheet keeps the first two columns and drops the rest.\n   */\n  protected readonly spalten = 'minmax(0, 2fr) 128px 96px 96px 40px';\n\n  /**\n   * Current page. A new filter delivers a new array, and the page jumps back to\n   * one, so nobody stares at an empty page two.\n   */\n  protected readonly seite = linkedSignal({ source: this.server, computation: () => 1 });\n\n  protected readonly sichtbar = computed(() => {\n    const start = (this.seite() - 1) * PRO_SEITE;\n    return this.server().slice(start, start + PRO_SEITE);\n  });\n\n  protected preis(server: BeispielServer): string {\n    return euro(server.kosten);\n  }\n}\n",
  "projects/beispiel-app/tsconfig.app.json": "/* To learn more about Typescript configuration file: https://www.typescriptlang.org/docs/handbook/tsconfig-json.html. */\n/* To learn more about Angular compiler options: https://angular.dev/reference/configs/angular-compiler-options. */\n{\n  \"extends\": \"../../tsconfig.json\",\n  \"compilerOptions\": {\n    \"types\": [],\n    /* The workspace root maps `zenit-ui` to the library sources, which is what\n       library development needs. This application is the proof that the built\n       package works, so it resolves the same specifier to `dist/zenit-ui`, the\n       folder `ng build zenit-ui` writes and `npm pack` would ship. Paths\n       without `baseUrl` are relative to this file. */\n    \"paths\": {\n      \"zenit-ui\": [\"../../dist/zenit-ui\"]\n    }\n  },\n  \"include\": [\"src/**/*.ts\"],\n  \"exclude\": [\"src/**/*.spec.ts\"]\n}\n",
  "angular.json (Auszug)": "\"beispiel-app\": {\n  \"architect\": {\n    \"build\": {\n      \"options\": {\n        \"styles\": [\n          \"dist/zenit-ui/styles/tokens.css\",\n          \"@angular/cdk/overlay-prebuilt.css\",\n          \"dist/zenit-ui/styles/themes.css\",\n          \"dist/zenit-ui/styles/zenit-ui.css\",\n          \"projects/beispiel-app/src/styles.css\"\n        ]\n      }\n    }\n  }\n}"
};
